mapper.select:
SELECT s.id, s.device_id, s.sensor_key, s.sensor_name, s.value, s.unit, s.collect_time
FROM sensor_data s
INNER JOIN (
    SELECT sensor_key, MAX(collect_time) AS max_time
    FROM sensor_data
    WHERE device_id = #{deviceId}
    GROUP BY sensor_key
) latest ON s.sensor_key = latest.sensor_key AND s.collect_time = latest.max_time
WHERE s.device_id = #{deviceId}
ORDER BY s.id DESC

SELECT id, device_id, sensor_key, sensor_name, value, unit, collect_time
FROM sensor_data
WHERE device_id = #{deviceId}
  AND sensor_key = #{sensorKey}
ORDER BY collect_time DESC, id DESC
LIMIT #{limit}
